#include "zs_bg95.h"
#include "zs_gnss.h"
#include "zs_sx1262.h"
#include "zs_audio.h"
#include <assert.h>
#include <stdio.h>
#include <string.h>
typedef struct{char uart[1024];size_t un;uint8_t spi[128];size_t sn;bool gpio[32];uint32_t ms;}mock_t;static uint32_t mm(void*c){return((mock_t*)c)->ms;}static void md(void*c,uint32_t v){((mock_t*)c)->ms+=v;}static int mu(void*c,unsigned ch,const uint8_t*d,size_t n){(void)ch;mock_t*m=c;if(m->un+n>=sizeof(m->uart))return-1;memcpy(m->uart+m->un,d,n);m->un+=n;m->uart[m->un]=0;return 0;}static int ms(void*c,unsigned bus,const uint8_t*t,uint8_t*r,size_t n){(void)bus;mock_t*m=c;if(n>sizeof(m->spi))return-1;memcpy(m->spi,t,n);m->sn=n;if(r)memset(r,0,n);return 0;}static void mgw(void*c,unsigned id,bool v){mock_t*m=c;if(id<32)m->gpio[id]=v;}static bool mgr(void*c,unsigned id){mock_t*m=c;return id<32?m->gpio[id]:false;}static zs_hal_port_t port(mock_t*m){return(zs_hal_port_t){.ctx=m,.millis=mm,.delay_ms=md,.uart_write=mu,.spi_transfer=ms,.gpio_write=mgw,.gpio_read=mgr};}static void test_bg95(void){mock_t m={0};zs_hal_port_t io=port(&m);zs_bg95_t b;zs_bg95_init(&b,&io,1,1,"private.apn");zs_bg95_power_on(&b,0);assert(b.state==ZS_BG95_POWERING);zs_bg95_tick(&b,700);assert(b.state==ZS_BG95_AT_SYNC);zs_bg95_tick(&b,700);assert(strstr(m.uart,"AT\r\n"));zs_bg95_on_line(&b,"OK",701);assert(strstr(m.uart,"AT+CPIN?"));zs_bg95_on_line(&b,"+CPIN: READY",702);assert(strstr(m.uart,"AT+CGDCONT=1,\"IP\",\"private.apn\""));zs_bg95_on_line(&b,"OK",703);assert(strstr(m.uart,"AT+CEREG?"));zs_bg95_on_line(&b,"+CEREG: 0,1",704);assert(zs_bg95_ready(&b));assert(b.network==ZS_BG95_NET_LTE);}static void test_gnss(void){zs_gnss_nmea_t g;zs_gnss_nmea_init(&g);assert(zs_gnss_parse_line(&g,"$GNGGA,123519,4807.038,N,01131.000,E,1,08,0.90,545.4,M,46.9,M,,"));assert(g.valid_fix&&g.satellites==8&&g.hdop_x100==90);assert(g.position.alt_dm==5454);assert(zs_gnss_parse_line(&g,"$GNRMC,123520,A,4807.038,N,01131.000,E,10.0,84.4,230394,,,A"));assert(g.rmc_valid);assert(g.course_cdeg==8440);}static void test_sx1262(void){mock_t m={0};zs_hal_port_t io=port(&m);zs_sx1262_t r;zs_sx1262_init(&r,&io,2,2,3,4);for(unsigned i=0;i<4;i++)assert(zs_ru868_channels_hz[i]!=869000000u);assert(zs_sx1262_set_frequency(&r,zs_ru868_channels_hz[1]));assert(r.frequency_hz==868300000u);assert(zs_sx1262_set_lora_modulation(&r,9,125000,5));assert(zs_sx1262_start_rx_duty_cycle(&r,500000,9500000));}static void test_audio(void){int16_t mem[8*4];zs_audio_ring_t r;zs_audio_ring_init(&r,mem,8,32000);for(int i=0;i<10;i++){int16_t f[4]={(int16_t)i,(int16_t)(i+10),(int16_t)(i+20),(int16_t)(i+30)};zs_audio_ring_push(&r,f);}int16_t o[4];assert(zs_audio_ring_copy_mono(&r,10,4,o,0));assert(o[0]==6&&o[3]==9);assert(zs_audio_ring_copy_average(&r,10,4,o));assert(o[0]==21&&o[3]==24);}int main(void){test_bg95();test_gnss();test_sx1262();test_audio();puts("zs_driver_tests: OK");return 0;}
